CREATE TABLE public.neutral_offer_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE CHECK(code ~ '^[a-f0-9]{48}$'), property_id uuid NOT NULL REFERENCES public.properties(id), organization_id uuid NOT NULL REFERENCES public.organizations(id), created_by uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
GRANT SELECT,INSERT,UPDATE ON public.neutral_offer_links TO authenticated;
GRANT ALL ON public.neutral_offer_links TO service_role;
ALTER TABLE public.neutral_offer_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY neutral_links_org ON public.neutral_offer_links TO authenticated USING(organization_id=public.current_org() AND EXISTS(SELECT 1 FROM public.properties p WHERE p.id=property_id AND p.organization_id=public.current_org() AND p.deleted_at IS NULL)) WITH CHECK(organization_id=public.current_org() AND created_by=auth.uid());
CREATE FUNCTION public.guard_neutral_offer_link() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN
IF TG_OP='INSERT' THEN IF NEW.created_by<>auth.uid() OR NEW.organization_id<>public.current_org() OR NOT EXISTS(SELECT 1 FROM properties WHERE id=NEW.property_id AND organization_id=NEW.organization_id AND status='active' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Oferta indisponibila'; END IF;
ELSIF ROW(NEW.id,NEW.code,NEW.property_id,NEW.organization_id,NEW.created_by,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.code,OLD.property_id,OLD.organization_id,OLD.created_by,OLD.created_at) OR (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at) THEN RAISE EXCEPTION 'Codul nu poate fi modificat sau reactivat'; END IF; RETURN NEW; END $$;
CREATE TRIGGER neutral_link_guard BEFORE INSERT OR UPDATE ON public.neutral_offer_links FOR EACH ROW EXECUTE FUNCTION public.guard_neutral_offer_link();
CREATE FUNCTION public.revoke_inactive_neutral_offers() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status<>'active' OR NEW.deleted_at IS NOT NULL THEN UPDATE neutral_offer_links SET revoked_at=coalesce(revoked_at,now()) WHERE property_id=NEW.id AND revoked_at IS NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER revoke_neutral_on_status AFTER UPDATE OF status,deleted_at ON public.properties FOR EACH ROW EXECUTE FUNCTION public.revoke_inactive_neutral_offers();
CREATE FUNCTION public.neutral_offer_text(_text text,_org uuid) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s text:=coalesce(_text,''); v text; BEGIN
FOR v IN SELECT name FROM organizations WHERE id=_org UNION SELECT full_name FROM profiles WHERE organization_id=_org UNION SELECT email FROM profiles WHERE organization_id=_org UNION SELECT phone FROM profiles WHERE organization_id=_org UNION SELECT email FROM organizations WHERE id=_org UNION SELECT phone FROM organizations WHERE id=_org LOOP IF length(trim(coalesce(v,'')))>2 THEN s:=regexp_replace(s,regexp_replace(v,'([.\\+*?\[\](){}^$|])','\\\1','g'),'','gi'); END IF; END LOOP;
s:=regexp_replace(s,'https?://[^\s]+|www\.[^\s]+|[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}|\+?[0-9][0-9 () .-]{7,}[0-9]','','gi');
s:=regexp_replace(s,'[^\n]*(Habitoo|agen[tț]ie|agen[tț]ia|agent |telefon|contact|whatsapp|facebook|instagram)[^\n]*','','gi'); RETURN trim(s); END $$;
REVOKE ALL ON FUNCTION public.neutral_offer_text(text,uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.public_neutral_offer(_code text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p properties; l neutral_offer_links; photos jsonb; fs jsonb; us jsonb; BEGIN
SELECT * INTO l FROM neutral_offer_links WHERE code=_code AND revoked_at IS NULL; IF NOT FOUND THEN RETURN NULL; END IF;
SELECT * INTO p FROM properties WHERE id=l.property_id AND status='active' AND deleted_at IS NULL; IF NOT FOUND THEN RETURN NULL; END IF;
SELECT coalesce(jsonb_agg(jsonb_build_object('index',n,'width',width,'height',height) ORDER BY n),'[]'::jsonb) INTO photos FROM (SELECT row_number() OVER(ORDER BY is_primary DESC,position,id)-1 n,width,height FROM property_images WHERE property_id=p.id AND include_in_publish AND NOT is_confidential AND storage_path IS NOT NULL AND storage_path NOT LIKE '%watermark%') i;
SELECT coalesce(jsonb_agg(public.neutral_offer_text(v,p.organization_id)),'[]') INTO fs FROM unnest(p.features) v; SELECT coalesce(jsonb_agg(public.neutral_offer_text(v,p.organization_id)),'[]') INTO us FROM unnest(p.utilities) v;
RETURN jsonb_build_object('reference',upper(left(l.code,8)),'title',coalesce(nullif(public.neutral_offer_text(p.title,p.organization_id),''),'Ofertă imobiliară'),'description',public.neutral_offer_text(p.description,p.organization_id),'price',p.price,'currency',p.currency,'transactionKind',p.transaction_kind,'propertyType',p.property_type,'rooms',p.rooms,'bathrooms',p.bathrooms,'surface',p.surface,'usableSurface',p.usable_surface,'landSurface',p.land_surface,'floor',p.floor,'buildYear',p.build_year,'city',public.neutral_offer_text(p.city,p.organization_id),'district',public.neutral_offer_text(p.district,p.organization_id),'features',fs,'utilities',us,'images',photos); END $$;
REVOKE ALL ON FUNCTION public.public_neutral_offer(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_neutral_offer(text) TO anon,authenticated,service_role;
CREATE FUNCTION public.neutral_offer_media(_code text,_index integer) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT i.storage_path FROM neutral_offer_links l JOIN properties p ON p.id=l.property_id JOIN property_images i ON i.property_id=p.id WHERE l.code=_code AND l.revoked_at IS NULL AND p.status='active' AND p.deleted_at IS NULL AND i.include_in_publish AND NOT i.is_confidential AND i.storage_path IS NOT NULL AND i.storage_path NOT LIKE '%watermark%' ORDER BY i.is_primary DESC,i.position,i.id OFFSET greatest(_index,0) LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.neutral_offer_media(text,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.neutral_offer_media(text,integer) TO service_role;
CREATE FUNCTION public.collaborator_offer_recipients() RETURNS TABLE(user_id uuid,full_name text,agency_name text,phone text,email text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.full_name,o.name,p.phone,p.email FROM profiles me JOIN organizations mine ON mine.id=me.organization_id CROSS JOIN profiles p JOIN organizations o ON o.id=p.organization_id WHERE me.id=auth.uid() AND mine.status IN('active','trial') AND mine.archived_at IS NULL AND mine.collaboration_enabled AND p.organization_id<>me.organization_id AND p.is_active AND o.status IN('active','trial') AND o.archived_at IS NULL AND o.collaboration_enabled ORDER BY o.name,p.full_name,p.id $$;
REVOKE ALL ON FUNCTION public.collaborator_offer_recipients() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.collaborator_offer_recipients() TO authenticated,service_role;
CREATE TABLE public.collaborator_offer_deliveries(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),agent_id uuid NOT NULL REFERENCES profiles(id),property_id uuid NOT NULL REFERENCES properties(id),link_id uuid NOT NULL REFERENCES neutral_offer_links(id),recipient_agent_id uuid REFERENCES profiles(id),recipient text NOT NULL,recipient_name text NOT NULL,channel text NOT NULL CHECK(channel IN('whatsapp','email','sms','copy')),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','failed','sent','logged')),sent_at timestamptz,activity_id uuid REFERENCES activities(id));
GRANT SELECT,INSERT,UPDATE ON public.collaborator_offer_deliveries TO authenticated;
GRANT ALL ON public.collaborator_offer_deliveries TO service_role;
ALTER TABLE public.collaborator_offer_deliveries ENABLE ROW LEVEL SECURITY;
CREATE POLICY collaborator_delivery_self ON public.collaborator_offer_deliveries TO authenticated USING(agent_id=auth.uid() AND organization_id=public.current_org()) WITH CHECK(agent_id=auth.uid() AND organization_id=public.current_org());
CREATE FUNCTION public.guard_collaborator_delivery() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM neutral_offer_links l JOIN properties p ON p.id=l.property_id WHERE l.id=NEW.link_id AND l.property_id=NEW.property_id AND l.organization_id=NEW.organization_id AND p.organization_id=public.current_org() AND p.deleted_at IS NULL) THEN RAISE EXCEPTION 'Oferta indisponibila'; END IF; IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.organization_id,NEW.agent_id,NEW.property_id,NEW.link_id,NEW.recipient_agent_id,NEW.recipient,NEW.recipient_name,NEW.channel) IS DISTINCT FROM ROW(OLD.id,OLD.organization_id,OLD.agent_id,OLD.property_id,OLD.link_id,OLD.recipient_agent_id,OLD.recipient,OLD.recipient_name,OLD.channel) THEN RAISE EXCEPTION 'Destinatarul nu poate fi modificat'; END IF; RETURN NEW; END $$;
CREATE TRIGGER collaborator_delivery_guard BEFORE INSERT OR UPDATE ON public.collaborator_offer_deliveries FOR EACH ROW EXECUTE FUNCTION public.guard_collaborator_delivery();
CREATE FUNCTION public.finish_collaborator_offer_delivery(_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE d collaborator_offer_deliveries; a uuid; BEGIN SELECT * INTO d FROM collaborator_offer_deliveries WHERE id=_id AND agent_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Trimitere indisponibila'; END IF; IF d.activity_id IS NOT NULL THEN RETURN d.activity_id; END IF; IF d.status<>'sent' THEN RAISE EXCEPTION 'Trimitere neconfirmata'; END IF;
INSERT INTO activities(organization_id,kind,title,description,starts_at,ends_at,done,status,duration_minutes,property_id,assigned_to,created_by) VALUES(d.organization_id,CASE WHEN d.channel='email' THEN 'email'::activity_kind ELSE 'note'::activity_kind END,'Ofertă trimisă colaboratorului',concat('Canal: ',d.channel,' · Destinatar: ',d.recipient_name,' · ',d.recipient,CASE WHEN d.channel='copy' THEN ' · Link copiat; livrarea nu este confirmată' ELSE '' END),coalesce(d.sent_at,now()),coalesce(d.sent_at,now()),true,'done',0,d.property_id,auth.uid(),auth.uid()) RETURNING id INTO a;
INSERT INTO audit_logs(organization_id,actor_id,action,entity,entity_id,new_values) VALUES(d.organization_id,auth.uid(),'Ofertă trimisă colaboratorului','properties',d.property_id,jsonb_build_object('channel',d.channel,'activity_id',a)); UPDATE collaborator_offer_deliveries SET activity_id=a,status='logged' WHERE id=d.id; RETURN a; END $$;
REVOKE ALL ON FUNCTION public.finish_collaborator_offer_delivery(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.finish_collaborator_offer_delivery(uuid) TO authenticated,service_role;